/* View menu button and dropdown */
#view-menu-btn {
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  padding: 4px 12px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  color: var(--text-primary);
  transition: background-color 0.15s;
}
#view-menu-btn:hover {
  background: var(--bg-tertiary);
}
.toolbar-anchor {
  position: relative;
}
#view-menu-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  margin-top: 4px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-primary);
  border-radius: 6px;
  box-shadow: 0 4px 16px var(--shadow);
  z-index: 50;
  min-width: 180px;
  padding: 4px 0;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}
#view-menu-dropdown.hidden {
  display: none;
}
#view-menu-dropdown label {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  font-size: 12px;
  cursor: pointer;
  transition: background-color 0.1s;
}
#view-menu-dropdown label:hover {
  background: var(--bg-secondary);
}
#view-menu-dropdown input[type="checkbox"] {
  width: 14px;
  height: 14px;
  cursor: pointer;
}
/* Preferences button */
#prefs-btn {
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  padding: 4px 8px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  color: var(--text-primary);
  transition: background-color 0.15s;
}
#prefs-btn:hover {
  background: var(--bg-tertiary);
}
/* Preferences modal */
#prefs-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
}
#prefs-overlay.hidden {
  display: none;
}
#prefs-modal {
  background: var(--bg-elevated);
  border: 1px solid var(--border-primary);
  border-radius: 8px;
  box-shadow: 0 8px 32px var(--shadow);
  width: 360px;
  max-height: 80vh;
  overflow-y: auto;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}
#prefs-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-primary);
}
#prefs-modal-header h2 {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
}
#prefs-close {
  background: none;
  border: none;
  font-size: 20px;
  cursor: pointer;
  color: var(--text-secondary);
  line-height: 1;
  padding: 2px 4px;
}
#prefs-close:hover {
  color: var(--text-primary);
}
.prefs-section {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-secondary);
}
.prefs-section:last-child {
  border-bottom: none;
}
.prefs-section h3 {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-tertiary);
  margin: 0 0 8px 0;
}
.prefs-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 0;
  font-size: 12px;
}
.prefs-row label {
  color: var(--text-primary);
}
.prefs-row select,
.prefs-row input[type="text"] {
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  border-radius: 4px;
  padding: 3px 6px;
  font-size: 12px;
  color: var(--text-primary);
  width: 100px;
}
.prefs-row input[type="color"] {
  width: 32px;
  height: 24px;
  border: 1px solid var(--border-primary);
  border-radius: 4px;
  padding: 1px;
  cursor: pointer;
  background: var(--bg-secondary);
}
.prefs-row button {
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  padding: 3px 10px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  color: var(--text-primary);
}
.prefs-row button:hover {
  background: var(--bg-tertiary);
}

